202:   function generateMap(seed) {
203:     const rand = rng(seed || Date.now());
204:     const grid = [];
205:     for (let y = 0; y < GRID; y++) for (let x = 0; x < GRID; x++) {
206:       grid.push({ terrain: 'grass', road: false, b: null });
207:     }
208:     const s = { grid };
209:     // main lake (lower-left of map)
210:     const lx = 18.2, ly = 17.4, lr = 2.9;
211:     for (let y = 0; y < GRID; y++) for (let x = 0; x < GRID; x++) {
212:       const d = Math.hypot(x - lx, (y - ly) * 1.2);
213:       if (d < lr + rand() * .55) grid[idx(x, y)].terrain = 'water';
214:       else if (d < lr + 1.05) grid[idx(x, y)].terrain = Math.random() < .6 ? 'sand' : 'grass';
215:     }
216:     // small pond
217:     for (let y = 0; y < GRID; y++) for (let x = 0; x < GRID; x++) {
218:       const d = Math.hypot(x - 3.6, (y - 20.2) * 1.15);
219:       if (d < 1.5 + rand() * .3) grid[idx(x, y)].terrain = 'water';
220:       else if (d < 2.1) grid[idx(x, y)].terrain = 'sand';
221:     }
222:     // scatter nature outside the central clearing
223:     const trees = [];
224:     for (let y = 0; y < GRID; y++) for (let x = 0; x < GRID; x++) {
225:       const t = grid[idx(x, y)];
226:       if (t.terrain !== 'grass') continue;
227:       const dc = Math.hypot(x - 12, y - 12);
228:       const edge = Math.min(x, y, GRID - 1 - x, GRID - 1 - y);
229:       let chance = 0;
230:       if (dc > 7.6) chance = .22;
231:       if (edge < 3) chance += .2;
232:       if (dc > 10) chance += .12;
233:       if (rand() < chance) trees.push({ defId: 'tree', x, y, level: 1, variant: Math.floor(rand() * 3) });
234:       else if (rand() < .018 && dc > 6.5) trees.push({ defId: 'rock', x, y, level: 1 });
235:     }
236:     return { grid, treeSeed: trees };
237:   }
