406:   const CAR_COLORS = ['#e6563d', '#3b8fd4', '#f2c94c', '#4fae62', '#c14b7c', '#f28b3c', '#6b7c8a', '#f7f4ec'];
407:   const VEHICLE_TYPES = ['car', 'car', 'car', 'motorcycle', 'motorcycle', 'bus', 'truck'];
408:   function newCar(tx, ty) {
409:     const choices = [];
410:     for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
411:       const nx = tx + dx, ny = ty + dy;
412:       if (inBounds(nx, ny) && state.grid[idx(nx, ny)].road) choices.push({ x: nx, y: ny, dx, dy });
413:     }
414:     if (!choices.length) return null;
415:     const c = choices[Math.floor(Math.random() * choices.length)];
416:     const type = VEHICLE_TYPES[Math.floor(Math.random() * VEHICLE_TYPES.length)];
417:     const speed = .45 + Math.random() * .35;
418:     return {
419:       x: tx + .5, y: ty + .5, fromX: tx + .5, fromY: ty + .5, toX: c.x + .5, toY: c.y + .5,
420:       t: 0, speed: speed * (type === 'bus' || type === 'truck' ? .78 : type === 'motorcycle' ? 1.12 : 1),
421:       type, color: type === 'bus' ? '#e5b83f' : type === 'truck' ? '#4d9b78' : CAR_COLORS[Math.floor(Math.random() * CAR_COLORS.length)],
422:       dir: c.dx > 0 ? 'x' : c.dx < 0 ? '-x' : c.dy > 0 ? 'y' : '-y', alive: true
423:     };
424:   }
425:   function carShape(car) {
426:     const dx = car.dir === 'x' ? 1 : car.dir === '-x' ? -1 : 0;
427:     const dy = car.dir === 'y' ? 1 : car.dir === '-y' ? -1 : 0;
428:     const vx = (dx - dy) * 32, vy = (dx + dy) * 16;
429:     const length = Math.hypot(vx, vy) || 1;
430:     const ux = vx / length, uy = vy / length;
431:     const px = (car.x - car.y) * 32 - uy * 4.8;
432:     const py = (car.x + car.y) * 16 + ux * 4.8;
433:     const halfLength = car.type === 'bus' || car.type === 'truck' ? 16 : car.type === 'motorcycle' ? 6.5 : 10;
434:     return { x: px, y: py, ux, uy, halfLength, halfWidth: 4.6 };
435:   }
436:   function carsOverlap(a, b) {
437:     const sa = carShape(a), sb = carShape(b);
438:     const axes = [[sa.ux, sa.uy], [-sa.uy, sa.ux], [sb.ux, sb.uy], [-sb.uy, sb.ux]];
439:     for (const [ax, ay] of axes) {
440:       const distance = Math.abs((sb.x - sa.x) * ax + (sb.y - sa.y) * ay);
441:       const ra = sa.halfLength * Math.abs(sa.ux * ax + sa.uy * ay) + sa.halfWidth * Math.abs(-sa.uy * ax + sa.ux * ay);
442:       const rb = sb.halfLength * Math.abs(sb.ux * ax + sb.uy * ay) + sb.halfWidth * Math.abs(-sb.uy * ax + sb.ux * ay);
443:       if (distance >= ra + rb) return false;
444:     }
445:     return true;
446:   }
447:   function nextCarState(car, dt, size, isRoad) {
448:     const next = { ...car };
449:     next.t += dt * next.speed;
450:     if (next.t >= 1) {
451:       const tx = Math.round(next.toX - .5), ty = Math.round(next.toY - .5);
452:       const prevDx = Math.sign(next.toX - next.fromX), prevDy = Math.sign(next.toY - next.fromY);
453:       next.fromX = next.toX; next.fromY = next.toY;
454:       const choices = [];
455:       for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
456:         const nx = tx + dx, ny = ty + dy;
457:         if (nx >= 0 && ny >= 0 && nx < size && ny < size && isRoad(nx, ny)) choices.push({ x: nx, y: ny, dx, dy });
458:       }
459:       if (!choices.length) { next.alive = false; return next; }
460:       const reverse = { dx: -prevDx, dy: -prevDy };
461:       const forward = choices.filter(pick => pick.dx !== reverse.dx || pick.dy !== reverse.dy);
462:       const options = forward.length ? forward : choices;
463:       const pick = options[Math.floor(Math.random() * options.length)];
464:       next.toX = pick.x + .5; next.toY = pick.y + .5;
465:       next.dir = pick.dx > 0 ? 'x' : pick.dx < 0 ? '-x' : pick.dy > 0 ? 'y' : '-y';
466:       next.t = 0;
467:     }
468:     next.x = lerp(next.fromX, next.toX, next.t);
469:     next.y = lerp(next.fromY, next.toY, next.t);
470:     return next;
471:   }
472:   function spawnCars(initial) {
473:     const roads = allRoads();
474:     if (!roads.length) return;
475:     const cap = Math.min(16, Math.floor(roads.length / 2.4));
476:     let attempts = 0;
477:     while (state.cars.length < cap && attempts++ < cap * 24) {
478:       const r = roads[Math.floor(Math.random() * roads.length)];
479:       const c = newCar(r.x, r.y);
480:       if (!c) continue;
481:       c.t = initial ? Math.random() : 0;
482:       c.x = lerp(c.fromX, c.toX, c.t); c.y = lerp(c.fromY, c.toY, c.t);
483:       if (state.cars.some(other => carsOverlap(c, other))) continue;
484:       state.cars.push(c);
485:     }
486:   }
487:   function ensureCars() { spawnCars(); }
488:   function updateCars(dt) {
489:     if (!state || !state.cars) return;
490:     const isRoad = (x, y) => state.grid[idx(x, y)].road;
491:     for (const c of state.cars) {
492:       if (!c.alive) continue;
493:       const next = nextCarState(c, dt, state.gridSize, isRoad);
494:       if (state.cars.some(other => other !== c && carsOverlap(next, other))) continue;
495:       Object.assign(c, next);
496:     }
497:     state.cars = state.cars.filter(c => c.alive);
498:     const roads = allRoads();
499:     if (state.cars.length < Math.min(14, Math.floor(roads.length / 2.4)) && Math.random() < .02) {
500:       const r = roads[Math.floor(Math.random() * roads.length)];
501:       if (r) {
502:         const c = newCar(r.x, r.y);
503:         if (c && !state.cars.some(other => carsOverlap(c, other))) state.cars.push(c);
504:       }
505:     }
506:   }
