163:     ctx.ellipse(x, y, rw * 1.1, rh * 1.7, 0, 0, Math.PI * 2);
164:     ctx.fill();
165:     for (const p of parts) {
166:       if (p[0] === 0 && p[1] === 0) continue;
167:       ctx.beginPath();
168:       ctx.ellipse(x + p[0] * rw, y + p[1] * rh, rw * .45 * p[2], rh * .8 * p[2], 0, 0, Math.PI * 2);
169:       ctx.fill();
170:     }
171:   }
