173:   // ---------- map plate ----------
174:   function drawPlate(ctx, grid) {
175:     const p = isoPts([[0, 0], [grid, 0], [grid, grid], [0, grid]]);
176:     const cx = 0, cy = grid * IY;
177:     const shadow = ctx.createRadialGradient(cx, cy + 40, 40, cx, cy + 40, grid * 42);
178:     shadow.addColorStop(0, 'rgba(3,35,42,.30)');
179:     shadow.addColorStop(.7, 'rgba(3,35,42,.10)');
180:     shadow.addColorStop(1, 'rgba(3,35,42,0)');
181:     ctx.save();
182:     ctx.translate(0, 34);
183:     ctx.scale(1.02, .88);
184:     ctx.fillStyle = shadow;
185:     ctx.beginPath(); ctx.ellipse(cx, cy, grid * 34, grid * 20, 0, 0, Math.PI * 2); ctx.fill();
186:     ctx.restore();
187:     const depth = 20;
188:     // visible cliff sides
189:     poly(ctx, [p[3], p[2], { x: p[2].x, y: p[2].y + depth }, { x: p[3].x, y: p[3].y + depth }], '#4e4032');
190:     poly(ctx, [p[2], p[1], { x: p[1].x, y: p[1].y + depth }, { x: p[2].x, y: p[2].y + depth }], '#64513e');
191:     poly(ctx, [p[3], p[0], { x: p[0].x, y: p[0].y + depth }, { x: p[3].x, y: p[3].y + depth }], '#3f3529');
192:     poly(ctx, [p[0], p[1], { x: p[1].x, y: p[1].y + depth }, { x: p[0].x, y: p[0].y + depth }], '#574636');
