199:   // ---------- terrain ----------
200:   const GRASS = ['#8bcb67', '#85c562', '#91d06d', '#7fbe5d', '#96d371'];
201:   const SAND = ['#e7d19a', '#e3ca8e', '#edd8a6'];
202:   function drawTerrain(ctx, world, x, y, tile, time) {
203:     const T = iso(x, y), R = iso(x + 1, y), B = iso(x + 1, y + 1), L = iso(x, y + 1);
204:     const h = hash(x, y);
205:     if (tile.terrain === 'water') {
206:       const base = h > .5 ? '#3d9fc0' : '#429fbe';
207:       poly(ctx, [T, R, B, L], base);
208:       const shimmer = (Math.sin(time * 1.1 + x * 1.7 + y * 2.3) + 1) / 2;
209:       ctx.globalAlpha = .18 + shimmer * .18;
210:       line(ctx, { x: T.x + 16, y: T.y + 10 }, { x: T.x + 25, y: T.y + 14.5 }, '#e9ffff', 1.4);
211:       line(ctx, { x: T.x + 9, y: T.y + 20 }, { x: T.x + 17, y: T.y + 24 }, '#d8fbff', 1.2);
212:       line(ctx, { x: T.x + 27, y: T.y + 21 }, { x: T.x + 35, y: T.y + 25 }, '#d8fbff', 1.1);
213:       ctx.globalAlpha = 1;
214:       // shoreline foam
215:       const foam = (dir) => {
216:         const n = neighbor(world, x, y, dir);
217:         if (!n || n.terrain === 'water') return;
218:         if (dir === 'n') line(ctx, T, R, 'rgba(240,255,255,.6)', 2.2);
219:         if (dir === 'e') line(ctx, R, B, 'rgba(240,255,255,.55)', 2);
220:         if (dir === 's') line(ctx, B, L, 'rgba(240,255,255,.55)', 1.8);
221:         if (dir === 'w') line(ctx, L, T, 'rgba(240,255,255,.6)', 2);
222:       };
223:       foam('n'); foam('e'); foam('s'); foam('w');
224:       return;
225:     }
226:     let base;
227:     if (tile.terrain === 'sand') base = SAND[Math.floor(h * SAND.length)];
228:     else base = GRASS[Math.floor(h * GRASS.length)];
229:     poly(ctx, [T, R, B, L], base);
230:     if (tile.terrain === 'grass') {
231:       ctx.strokeStyle = 'rgba(45,100,40,.055)'; ctx.lineWidth = .8;
232:       ctx.stroke();
233:       if (h > .32) {
234:         const gx = T.x + 10 + hash(x + 3, y) * 30;
235:         const gy = T.y + 9 + hash(x, y + 5) * 12;
236:         ctx.globalAlpha = .35;
237:         line(ctx, { x: gx, y: gy }, { x: gx + 1.5, y: gy - 3.4 }, '#4d8a3e', 1);
238:         line(ctx, { x: gx + 1, y: gy }, { x: gx + 4, y: gy - 2.8 }, '#4d8a3e', .9);
239:         line(ctx, { x: gx + 1, y: gy }, { x: gx - 1.7, y: gy - 2.6 }, '#5a9648', .9);
240:         if (h > .75) {
241:           ctx.fillStyle = h > .9 ? '#f7d85e' : '#f2fdf8';
242:           ctx.beginPath(); ctx.arc(gx + 6, gy - 3, 1.15, 0, 7); ctx.fill();
243:         }
244:         ctx.globalAlpha = 1;
245:       }
246:     } else if (tile.terrain === 'sand') {
247:       ctx.globalAlpha = .28;
248:       ctx.fillStyle = '#b99f66';
249:       for (let i = 0; i < 2; i++) {
250:         const sx = T.x + 12 + hash(x + i, y + 1) * 30;
251:         const sy = T.y + 8 + hash(x + 2, y + i) * 12;
252:         ctx.beginPath(); ctx.arc(sx, sy, .9, 0, 7); ctx.fill();
253:       }
254:       ctx.globalAlpha = 1;
255:     }
256:   }
257:   // Directions match the four visible diamond edges: n=T-R (+x), e=R-B (+y),
258:   // s=B-L (-x), and w=L-T (-y).
259:   function neighbor(world, x, y, dir) {
260:     const dx = dir === 'n' ? 1 : dir === 's' ? -1 : 0;
261:     const dy = dir === 'e' ? 1 : dir === 'w' ? -1 : 0;
262:     const nx = x + dx, ny = y + dy;
263:     if (nx < 0 || ny < 0 || nx >= world.gridSize || ny >= world.gridSize) return null;
264:     return world.grid[ny * world.gridSize + nx];
265:   }
266:   function isRoad(world, x, y) {
267:     if (x < 0 || y < 0 || x >= world.gridSize || y >= world.gridSize) return false;
268:     return world.grid[y * world.gridSize + x].road;
269:   }
270:   function drawRoad(ctx, world, x, y, tile) {
271:     const T = iso(x, y), R = iso(x + 1, y), B = iso(x + 1, y + 1), L = iso(x, y + 1);
272:     const col = '#505a62';
273:     // Keep the road surface clean; vehicles define the lanes as they pass.
274:     poly(ctx, [T, R, B, L], col);
275:   }
