277:   // ---------- building primitives ----------
278:   function boxGeo(x, y, w, h, inset) {
279:     const i = inset == null ? .07 : inset;
280:     return {
281:       T: iso(x + i, y + i), R: iso(x + w - i, y + i), B: iso(x + w - i, y + h - i), L: iso(x + i, y + h - i)
282:     };
283:   }
284:   function drawBox(ctx, x, y, w, h, height, opt) {
285:     const o = opt || {};
286:     const g = boxGeo(x, y, w, h, o.inset);
287:     const wall = o.wall || '#f0e3c8';
288:     const left = o.left || shade(wall, .84);
289:     const right = o.right || shade(wall, .67);
290:     const top = o.top || wall;
291:     const up = (p, dy) => ({ x: p.x, y: p.y - (dy || height) });
292:     poly(ctx, [g.L, g.B, up(g.B), up(g.L)], left);
293:     poly(ctx, [g.B, g.R, up(g.R), up(g.B)], right);
294:     poly(ctx, [up(g.T), up(g.R), up(g.B), up(g.L)], top);
295:     if (o.outline !== false) {
296:       ctx.strokeStyle = o.outlineColor || 'rgba(20,42,32,.16)';
297:       ctx.lineWidth = .8;
298:       poly(ctx, [g.L, g.B, up(g.B), up(g.L)], null, ctx.strokeStyle, .8);
299:       poly(ctx, [g.B, g.R, up(g.R), up(g.B)], null, ctx.strokeStyle, .8);
300:     }
301:     return { g, height, up, top: top };
302:   }
303:   function drawPitchedRoof(ctx, g, height, rise, color, opt) {
304:     const o = opt || {};
305:     const y = height;
306:     const T = { x: g.T.x, y: g.T.y - y }, R = { x: g.R.x, y: g.R.y - y }, B = { x: g.B.x, y: g.B.y - y }, L = { x: g.L.x, y: g.L.y - y };
307:     const cx = (T.x + B.x) / 2, cy = (T.y + B.y) / 2;
308:     const apex = { x: cx, y: cy - rise };
309:     const over = o.over || 0;
310:     if (over) {
311:       const dirs = [[T, R], [R, B], [B, L], [L, T]];
312:       for (const [a, b] of dirs) {
313:         const na = { x: a.x + (a.x - cx) * .06, y: a.y + (a.y - cy) * .06 };
314:         const nb = { x: b.x + (b.x - cx) * .06, y: b.y + (b.y - cy) * .06 };
315:         poly(ctx, [a, b, nb, na], shade(color, .7));
316:       }
317:     }
318:     poly(ctx, [L, B, apex], shade(color, .86));
319:     poly(ctx, [B, R, apex], shade(color, .66));
320:     if (o.ridge !== false) {
321:       line(ctx, apex, { x: lerp(L.x, B.x, .5), y: lerp(L.y, B.y, .5) - rise * .0 }, shade(color, .55), 1.2);
322:     }
323:     if (o.tiles) {
324:       ctx.globalAlpha = .18;
325:       for (let i = 1; i <= 3; i++) {
326:         const t = i / 4;
327:         const a = { x: lerp(L.x, B.x, t / 2), y: lerp(L.y, B.y, t / 2) };
328:         const b = { x: lerp(apex.x, B.x, t * .8), y: lerp(apex.y, B.y, t * .8) };
329:         line(ctx, { x: lerp(L.x, B.x, 1 - t), y: lerp(L.y, B.y, 1 - t) }, { x: lerp(apex.x, L.x, .5), y: lerp(apex.y, L.y, .5) }, shade(color, .5), .8);
330:       }
331:       ctx.globalAlpha = 1;
332:     }
333:   }
334:   function drawWindows(ctx, faceA, faceB, height, rows, cols, opt) {
335:     const o = opt || {};
336:     const top = o.top || 6, bottom = o.bottom || 7;
337:     const usable = height - top - bottom;
338:     if (usable < 6) return;
339:     const winH = Math.min(o.winH || 6, usable / rows * .5);
340:     const winW = o.winW || 4.6;
341:     const col = NIGHT > .28 ? '#ffd98a' : (o.color || '#bfe6f5');
342:     const frame = o.frame || 'rgba(255,255,255,.28)';
343:     const stepX = (faceB.x - faceA.x) / cols;
344:     const stepY = (faceB.y - faceA.y) / cols;
345:     for (let r = 0; r < rows; r++) {
346:       const wy = height - top - (usable / rows) * (r + .5);
347:       for (let c = 0; c < cols; c++) {
348:         const cx = faceA.x + stepX * (c + .5);
349:         const cy = faceA.y + stepY * (c + .5) - wy;
350:         const ex = (stepX / Math.abs(stepX || 1)) * winW;
351:         ctx.beginPath();
352:         ctx.moveTo(cx - ex / 2, cy);
353:         ctx.lineTo(cx + ex / 2, cy);
354:         ctx.lineTo(cx + ex / 2, cy + winH);
355:         ctx.lineTo(cx - ex / 2, cy + winH);
356:         ctx.closePath();
357:         ctx.fillStyle = col; ctx.fill();
358:         if (o.frame !== false) {
359:           ctx.strokeStyle = frame; ctx.lineWidth = .5; ctx.stroke();
360:         }
361:         if (NIGHT > .28) {
362:           ctx.globalAlpha = .18;
363:           ctx.fillStyle = '#ffe7a8';
364:           ctx.fillRect(cx - ex / 2 - 1, cy - 1, Math.abs(ex) + 2, winH + 2);
365:           ctx.globalAlpha = 1;
366:         }
367:       }
368:     }
369:   }
370:   function drawDoor(ctx, g, height, color, opt) {
371:     const o = opt || {};
372:     const frac = o.frac == null ? .5 : o.frac;
373:     const dx = lerp(g.L.x, g.B.x, frac), dy = lerp(g.L.y, g.B.y, frac);
374:     const w = o.w || 5, h = o.h || 10;
375:     poly(ctx, [
376:       { x: dx - w / 2, y: dy - h }, { x: dx + w / 2, y: dy - h },
377:       { x: dx + w / 2, y: dy }, { x: dx - w / 2, y: dy }
378:     ], color || '#7a5a3a');
379:     ctx.fillStyle = 'rgba(255,255,255,.18)';
380:     ctx.fillRect(dx + w / 2 - 1.6, dy - h / 2, 1, 1);
381:   }
382:   function drawAwning(ctx, g, height, colorA, colorB, y) {
383:     const baseY = y == null ? height - 13 : y;
384:     const segments = 6;
385:     for (let i = 0; i < segments; i++) {
386:       const t0 = i / segments, t1 = (i + 1) / segments;
387:       const a0 = { x: lerp(g.L.x, g.B.x, t0), y: lerp(g.L.y, g.B.y, t0) - baseY };
388:       const a1 = { x: lerp(g.L.x, g.B.x, t1), y: lerp(g.L.y, g.B.y, t1) - baseY };
389:       const b0 = { x: a0.x + 2, y: a0.y + 4 }, b1 = { x: a1.x + 2, y: a1.y + 4 };
390:       poly(ctx, [a0, a1, b1, b0], i % 2 ? colorB : colorA);
391:     }
392:   }
393:   function addVariantColors(b, palettes) {
