398:   // object dispatch & main render (art functions below)
399:   function defOf(b) { return DEFS[b.defId]; }
400:   function artFor(def, level) {
401:     if (def.kind === 'zone-r') return level > 0 ? 'house' : 'lot_r';
402:     if (def.kind === 'zone-c') return level > 0 ? 'shop' : 'lot_c';
403:     if (def.kind === 'zone-i') return level > 0 ? 'factory' : 'lot_i';
404:     return def.art;
405:   }
406:   function artHeight(def, level) {
407:     const lv = level || 1;
408:     if (def.kind === 'zone-r') return [0, 52, 64, 80, 100][Math.min(lv, 4)];
409:     if (def.kind === 'zone-c') return [0, 48, 64, 84][Math.min(lv, 3)];
410:     if (def.kind === 'zone-i') return [0, 68, 80, 92][Math.min(lv, 3)];
411:     const map = {
412:       powerplant: 112, watertower: 78, solar: 46, police: 54, fire: 60, school: 86, hospital: 96,
413:       smallpark: 54, park: 74, plaza: 64, fountain: 58, ferris: 126, stadium: 100, monument: 96,
414:       tree: 58, flowers: 44, streetlamp: 54, rock: 36, lot_r: 34, lot_c: 34, lot_i: 34
415:     };
