441:       case 'shop': return drawShop(ctx, b, def, time);
442:       case 'factory': return drawFactory(ctx, b, def, time);
443:       case 'powerplant': return drawPowerPlant(ctx, b, time);
444:       case 'watertower': return drawWaterTower(ctx, b, time);
445:       case 'solar': return drawSolar(ctx, b, time);
446:       case 'police': return drawPolice(ctx, b, time);
447:       case 'fire': return drawFire(ctx, b, time);
448:       case 'school': return drawSchool(ctx, b, time);
449:       case 'hospital': return drawHospital(ctx, b, time);
450:       case 'smallpark': return drawSmallPark(ctx, b, time);
451:       case 'park': return drawPark(ctx, b, time);
452:       case 'plaza': return drawPlaza(ctx, b, time);
453:       case 'fountain': return drawFountain(ctx, b, time);
454:       case 'ferris': return drawFerris(ctx, b, time);
455:       case 'stadium': return drawStadium(ctx, b, time);
456:       case 'monument': return drawMonument(ctx, b, time);
457:       case 'tree': return drawTree(ctx, b, def, time);
458:       case 'flowers': return drawFlowers(ctx, b, time);
